    $$("[data-q]", T).forEach((b) => (b.onclick = async () => { let note = ""; if (b.dataset.s === "fail") { note = root.prompt ? root.prompt("What failed?") : ""; if (!note) return; }
      run(async () => { await FA().mutate(oid, (x) => { Object.assign(x.qc[+b.dataset.q], { status: b.dataset.s, note, by: meId(), at: new Date().toISOString() }); }, `QC ${b.dataset.s}`, note);
        if (b.dataset.s === "fail") await DPNotify.deliver(["@admins", j.salesUid], { id: `fac-qcf-${oid}-${Date.now().toString(36)}`, type: "factory", title: "Quality inspection failed", body: `${j.name} (${j.jobId}): ${note}`, ref: oid, link: { view: "proposals", opts: { oid } }, priority: "warning" }).catch(() => {}); }); }));
